// P25 in the pure port (no hybrid): whole movies through src/headless.js against the oracle (RAM + SRAM,
// every frame), diff 0 required.
//  * death-continue: Link dies 3 times (mode $11, all 13 submodes) -> mode 8: CONTINUE after cycling
//    the cursor, SAVE (mode $D) and RETRY (mode 0 submode 1). Generated by tests/game/p25-make-movies.mjs.
//  * save-and-continue: mode 8 from the submenu (pad 2 Up+A), SAVE (tests/game/p24-movies.mjs).
//  * triforce-level1: level 1 to Aquamentus, triforce piece: mode $12 (all 5 submodes) and EndGameMode12
//    (tests/game/p10-make-movies.mjs, SRAM p10-items.sav).
// Mode $13 (ending and credits) is checked by ending-from-ganon once P22 (Ganon, Zelda) is ported, and
// routine by routine in p25-routines.test.mjs. Skipped without roms/zelda.nes or jsnes.
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { join, basename } from 'node:path';
import { readFileSync, existsSync } from 'node:fs';
import { hasJsnes } from '../../tools/oracle/lib/jsnes-loader.mjs';
import { romExists, loadRomFile } from '../../tools/oracle/lib/rom-file.mjs';
import { loadMovie } from '../../tools/oracle/lib/movie.mjs';
import { TraceCollector } from '../../tools/oracle/lib/trace.mjs';
import { compareTraces, loadIgnoreConfig } from '../../tools/oracle/lib/diff-core.mjs';
import { runPort } from '../../tools/oracle/lib/port-adapter.mjs';
import { ROOT } from '../core/helpers.mjs';

const skip = !romExists() ? 'roms/zelda.nes not present' : !(await hasJsnes()) ? 'jsnes not installed' : false;
const MOVIES = join(ROOT, 'tests/oracle/movies');
// Modes each movie must go through in the original.
const REQUIRED = {
  'death-continue': [0x11, 0x08, 0x03, 0x0d, 0x01, 0x00],
  'save-and-continue': [0x08, 0x0d],
  'triforce-level1': [0x12, 0x02],
};

for (const name of Object.keys(REQUIRED)) {
  const missing = !existsSync(join(MOVIES, `${name}.zmv`)) && `${name}.zmv not generated`;
  test(`P25 pure port ${name}: diff 0 on every frame`, { skip: skip || missing, timeout: 1800000 }, async (t) => {
    const rom = loadRomFile();
    const expect = JSON.parse(readFileSync(join(MOVIES, `${name}.expect.json`), 'utf8'));
    const sram = expect.sram ? new Uint8Array(readFileSync(join(MOVIES, basename(expect.sram)))) : null;
    const movie = loadMovie(join(MOVIES, `${name}.zmv`));
    const { Oracle } = await import('../../tools/oracle/lib/nes-oracle.mjs');
    const V = await import('../../src/core/vars.js');
    const a = new TraceCollector({});
    const seen = {};
    for (const v of Object.keys(expect.reaches ?? {})) seen[v] = new Set();
    const modes = new Set();
    (await Oracle.create({ rom: rom.bytes, sram, powerOnFill: 0 })).run(movie, {
      write(rec) {
        a.write(rec);
        modes.add(rec.ram[V.GameMode]);
        for (const v of Object.keys(seen)) seen[v].add(rec.ram[V[v]]);
      },
      close() {},
    });
    for (const m of REQUIRED[name]) assert.ok(modes.has(m), `${name}: never in mode $${m.toString(16)}`);
    for (const [v, values] of Object.entries(expect.reaches ?? {})) {
      for (const value of values) assert.ok(seen[v].has(value), `${name}: ${v} never reaches ${value}`);
    }
    const b = new TraceCollector({});
    await runPort({ rom: rom.bytes, sram, inputs: movie, sink: b });
    t.diagnostic(`${b.frames.length} frames`);
    const report = compareTraces(a, b, { ignore: loadIgnoreConfig().ignore, compareFb: false });
    const first = report.frames[0];
    assert.equal(report.divergentFrames, 0, `${name}: first divergence at frame ${report.firstDivergence}: `
      + JSON.stringify(first && { ram: first.ram.slice(0, 8), sram: first.sram.slice(0, 8) }));
  });
}
